QUIZ_BANK_EXTRA["rc-low-pass-filter"] = RC_LOW_PASS_EXTRA


def merge_quiz_bank(base: dict) -> dict:
    """Return a new bank with extras appended per experiment (no mutation of base lists)."""
    merged = {}
    for experiment_id, questions in base.items():
        extra = QUIZ_BANK_EXTRA.get(experiment_id, [])
        merged[experiment_id] = list(questions) + list(extra)
    return merged
